WITH CustomerInfo AS ( SELECT c.c_customer_sk, c.c_first_name, c.c_last_name, cd.cd_gender, cd.cd_marital_status, cd.cd_education_status, cd.cd_purchase_estimate, hd.hd_income_band_sk, hd.hd_buy_potential, ROW_NUMBER() OVER (PARTITION BY c.c_customer_sk ORDER BY cd.cd_purchase_estimate DESC) AS rn FROM customer c JOIN customer_demographics cd ON c.c_current_cdemo_sk = cd.cd_demo_sk JOIN household_demographics hd ON cd.cd_demo_sk = hd.hd_demo_sk ), SalesInfo AS ( SELECT ws.ws_ship_customer_sk, SUM(ws.ws_ext_sales_price) AS total_sales, COUNT(ws.ws_order_number) AS order_count FROM web_sales ws GROUP BY ws.ws_ship_customer_sk ), ReturnsInfo AS ( SELECT wr.wr_returning_customer_sk, SUM(wr.wr_return_amt) AS total_returns, COUNT(wr.wr_order_number) AS return_count FROM web_returns wr GROUP BY wr.wr_returning_customer_sk ) SELECT ci.c_customer_sk, ci.c_first_name, ci.c_last_name, ci.cd_gender, ci.cd_marital_status, ci.cd_education_status, ci.cd_purchase_estimate, si.total_sales, si.order_count, ri.total_returns, ri.return_count, ci.hd_income_band_sk, ci.hd_buy_potential FROM CustomerInfo ci LEFT JOIN SalesInfo si ON ci.c_customer_sk = si.ws_ship_customer_sk LEFT JOIN ReturnsInfo ri ON ci.c_customer_sk = ri.wr_returning_customer_sk WHERE ci.rn = 1 AND (si.total_sales > 5000 OR ri.total_returns > 100) ORDER BY total_sales DESC, total_returns ASC;

